package com.flowdesk.alert.recovery;

import com.flowdesk.alert.event.AlertEventContract;import com.flowdesk.alert.event.TicketResultConsumer;import com.flowdesk.alert.event.TicketResultTransportMessage;import com.flowdesk.common.tenant.ActorRef;import com.flowdesk.common.tenant.TenantContext;import com.flowdesk.common.tenant.TenantContextScope;import org.springframework.core.task.TaskExecutor;import org.springframework.transaction.PlatformTransactionManager;import org.springframework.transaction.support.TransactionTemplate;import tools.jackson.databind.JsonNode;import tools.jackson.databind.ObjectMapper;import java.time.Instant;import java.time.format.DateTimeFormatter;import java.time.format.DateTimeFormatterBuilder;import java.time.temporal.ChronoUnit;import java.util.HexFormat;import java.util.LinkedHashMap;import java.util.Map;import java.util.UUID;
final class AlertRecoveryWorker{private static final ObjectMapper JSON=new ObjectMapper();private static final DateTimeFormatter MICROS=new DateTimeFormatterBuilder().appendInstant(6).toFormatter();private final TaskExecutor executor;private final AlertRecoveryRepository repository;private final TicketResultConsumer consumer;private final TransactionTemplate transactions;AlertRecoveryWorker(TaskExecutor e,AlertRecoveryRepository r,TicketResultConsumer c,PlatformTransactionManager tx){executor=e;repository=r;consumer=c;transactions=new TransactionTemplate(tx);}void submit(AlertRecoveryService.Work w){try{executor.execute(()->execute(w));}catch(RuntimeException e){settleFailure(w,"RECOVERY_REPLAY_WORKER_UNAVAILABLE");}}
    private void execute(AlertRecoveryService.Work w){var task=TenantContext.ofPersistedTask(w.tenant(),ActorRef.human(w.actor()),w.attempt());try(TenantContextScope ignored=TenantContextScope.open(task)){var recovery=repository.find(w.tenant(),w.recovery(),false).orElse(null);var source=repository.inbox(w.tenant(),w.source(),false).orElse(null);if(recovery==null||source==null||!"REPLAYING".equals(recovery.state())||!w.attempt().equals(recovery.replayCorrelation())||!"RECOVERY_REQUIRED".equals(source.status()))return;var result=consumer.consume(restore(w.tenant(),source));if(result==TicketResultConsumer.Result.RETRY)settleFailure(w,"RECOVERY_REPLAY_NOT_TERMINAL");else settleCompletion(w);}catch(RuntimeException e){settleFailure(w,"RECOVERY_REPLAY_EXECUTION_FAILED");}}
    private TicketResultTransportMessage restore(UUID tenant,AlertRecoveryRepository.Inbox s){if(!AlertEventContract.TICKET_ESTABLISHED.contractRef().equals(s.contractRef()))throw new IllegalStateException("Inactive Alert Inbox replay contract");try{JsonNode p=JSON.readTree(s.body());UUID aggregate=UUID.fromString(p.get("incidentId").stringValue());Map<String,String> h=new LinkedHashMap<>();h.put("fd_envelope_version","1");h.put("fd_event_type",AlertEventContract.TICKET_ESTABLISHED.eventType());h.put("fd_contract_ref",s.contractRef());h.put("fd_contract_version","1");h.put("fd_producer",AlertEventContract.TICKET_ESTABLISHED.producer());h.put("fd_tenant_id",tenant.toString());h.put("fd_message_id",s.messageId().toString());h.put("fd_business_intent_key",HexFormat.of().formatHex(s.intent()));h.put("fd_aggregate_type","INCIDENT");h.put("fd_aggregate_id",aggregate.toString());h.put("fd_correlation_id",s.correlation().toString());if(s.causation()!=null)h.put("fd_causation_id",s.causation().toString());h.put("fd_occurred_at",MICROS.format(s.occurred()));h.put("fd_body_sha256",HexFormat.of().formatHex(s.hash()));return new TicketResultTransportMessage(AlertEventContract.TICKET_ESTABLISHED.topic(),AlertEventContract.TICKET_ESTABLISHED.consumerGroup(),s.messageId().toString(),null,s.body(),h);}catch(Exception e){throw new IllegalStateException("Persisted Alert replay source is invalid",e);}}
    private void settleCompletion(AlertRecoveryService.Work w){transactions.executeWithoutResult(tx->{var r=repository.find(w.tenant(),w.recovery(),true).orElse(null);var s=repository.inbox(w.tenant(),w.source(),true).orElse(null);if(r==null||s==null||!"RESOLVED".equals(r.state())||!("PROCESSED".equals(s.status())||"REJECTED".equals(s.status()))){reopen(w,"RECOVERY_REPLAY_NOT_TERMINAL");return;}String outcome="PROCESSED".equals(s.status())?"SUCCEEDED":"REJECTED";UUID audit=AlertRecoveryIdempotency.outcomeAuditId(w.tenant(),w.attempt(),outcome);if(repository.audit(w.tenant(),audit).isEmpty())repository.audit(w.tenant(),audit,"ALERT_RECOVERY_REPLAY_COMPLETED",w.recovery(),outcome,w.actor(),w.reason(),"REJECTED".equals(outcome)?"REJECTED":null,w.attempt(),w.sourceCorrelation(),now());});}
    private void settleFailure(AlertRecoveryService.Work w,String code){transactions.executeWithoutResult(tx->reopen(w,code));}private void reopen(AlertRecoveryService.Work w,String code){Instant now=now();if(repository.reopen(w.tenant(),w.recovery(),w.attempt(),code,now)==1){UUID audit=AlertRecoveryIdempotency.outcomeAuditId(w.tenant(),w.attempt(),"FAILED");if(repository.audit(w.tenant(),audit).isEmpty())repository.audit(w.tenant(),audit,"ALERT_RECOVERY_REPLAY_COMPLETED",w.recovery(),"FAILED",w.actor(),w.reason(),code,w.attempt(),w.sourceCorrelation(),now);}}private static Instant now(){return Instant.now().truncatedTo(ChronoUnit.MICROS);}}
